require('dotenv').config()
const express = require('express')
const axios = require('axios')
const path = require('path')
const app = express()
const port = 5000

process.env.LANG = 'zh_CN.UTF-8';
process.env.LC_ALL = 'zh_CN.UTF-8';

app.use(express.json({ limit: '10mb', charset: 'utf-8' }))
app.use(express.urlencoded({ extended: true, limit: '10mb', charset: 'utf-8' }))

// 静态文件目录：相对本文件定位，换机器/换路径都能用
const staticPath = path.join(__dirname, '..', '软件开发（deepseek）')
console.log('静态文件路径:', staticPath)
app.use(express.static(staticPath))

// 测试路由
app.get('/test', (req, res) => {
  res.send('服务器运行正常，静态文件路径: ' + staticPath)
})

app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*')
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS')
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization')
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200)
  }
  next()
})

const users = []
const phoneReg = /^1\d{10}$/

function maskPhone(phone) {
  return phone.replace(/(\d{3})\d{4}(\d{4})/, '$1****$2')
}

app.post('/api/register', (req, res) => {
  const { phone, password } = req.body
  
  if (!phone || !phoneReg.test(phone)) {
    return res.json({ success: false, message: '请输入正确的11位手机号码' })
  }
  
  if (!password || password.length < 6) {
    return res.json({ success: false, message: '密码长度不能少于6位' })
  }
  
  if (password.includes(' ')) {
    return res.json({ success: false, message: '密码不能包含空格' })
  }
  
  const existingUser = users.find(u => u.phone === phone)
  if (existingUser) {
    return res.json({ success: false, message: '该手机号已注册，请直接登录' })
  }
  
  users.push({ phone, password, createdAt: Date.now() })
  console.log('新用户注册:', phone, '，当前用户数:', users.length)
  
  res.json({ success: true, message: '注册成功' })
})

app.post('/api/login', (req, res) => {
  const { phone, password } = req.body
  
  if (!phone || !phoneReg.test(phone)) {
    return res.json({ success: false, message: '请输入正确的11位手机号码' })
  }
  
  const user = users.find(u => u.phone === phone)
  
  if (!user) {
    return res.json({ success: false, message: '该手机号尚未注册，请先去注册' })
  }
  
  if (user.password !== password) {
    return res.json({ success: false, message: '密码错误' })
  }
  
  console.log('用户登录:', phone)
  res.json({
    success: true,
    message: '登录成功',
    data: {
      phone: phone,
      maskedPhone: maskPhone(phone),
      token: 'login_' + Date.now()
    }
  })
})

